import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { isColorValue } from '@cetus/utils'
import { Center, HTMLChakraProps } from '@chakra-ui/react'
import { useMemo, useState } from 'react'

// 定义可选的 variant 类型
export type VariantType = 'solid' | 'gray' | 'rectangle' | '' | 'error' | 'warning' | 'primary' | 'round'

// Icon 组件的 props
export interface IconProps extends HTMLChakraProps<'div'> {
  xlinkHref: string // svg 图标引用
  svgW?: string
  svgH?: string
  boxW?: string
  boxH?: string
  iconCursor?: 'text' | 'pointer' | 'not-allowed' | 'default'
  svgHover?: string
  svgFill?: string
  variant?: VariantType
  onClick?: (e: any) => void
  isActive?: boolean
  activeColor?: string
  activeHoverColor?: string
}

/**
 * Icon 组件
 *
 * variant 说明:
 *  ''       : 默认，不带背景，hover 变为白色
 *  solid    : 带背景，正方形
 *  gray     : 不带背景，灰色系，hover 变白色
 *  primary  : 不带背景，hover 变主题色
 *  warning  : 警告态
 *  error    : 错误态
 *  rectangle: 带背景，长方形
 *  round    : 带背景，圆形
 */
export default function Icon(props: IconProps) {
  const {
    xlinkHref,
    fontSize,
    svgW,
    svgH,
    boxW,
    boxH,
    variant = '',
    svgHover,
    svgFill,
    onClick,
    iconCursor = 'pointer',
    isActive,
    activeColor,
    activeHoverColor,
    ...rest
  } = props

  // 控制点击状态（用于移动端 hover）
  const [clicked, setClicked] = useState(false)
  const { isApp } = useWindowWidth()

  // 点击事件处理
  const handleClick = (e: React.MouseEvent) => {
    if (isApp) setClicked(true) // 移动端点击时记录点击态
    onClick?.(e)
  }

  /**
   * 根据 props 计算最终样式
   */
  const style = useMemo(() => {
    // 统一宽高优先级：单独 boxW/boxH > fontSize > 默认值
    const defaultSize = fontSize || '20px'
    const baseW = boxW || defaultSize
    const baseH = boxH || defaultSize

    // 统一 svg 填充色逻辑
    const getSvgFill = (defaultColor: string) => {
      if (isActive && activeColor) {
        return isColorValue(activeColor) ? activeColor : `var(--chakra-colors-${activeColor})`
      }
      if (svgFill) {
        return isColorValue(svgFill) ? svgFill : `var(--chakra-colors-${svgFill})`
      }
      return `var(--chakra-colors-${defaultColor})`
    }

    // hover 时的 svg 填充色
    const getSvgHoverFill = (defaultHover: string) => {
      if (isActive && activeHoverColor) return activeHoverColor
      return svgHover || defaultHover
    }

    // 定义各个 variant 的样式映射
    const variants = {
      base: {
        box: {
          w: baseW,
          h: baseH,
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: getSvgHoverFill('text_caption') }
                }
              : undefined
        },
        svg: {
          fill: getSvgFill('text_paragraph'),
          width: svgW || defaultSize,
          height: svgH || defaultSize
        }
      },
      gray: {
        box: {
          w: baseW,
          h: baseH,
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'text_caption' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || defaultSize,
          height: svgH || defaultSize
        }
      },
      primary: {
        box: {
          w: baseW,
          h: baseH,
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'primary' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || defaultSize,
          height: svgH || defaultSize
        }
      },
      warning: {
        box: {
          w: baseW,
          h: baseH,
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'primary_yellow' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary_yellow)',
          width: svgW || defaultSize,
          height: svgH || defaultSize
        }
      },
      error: {
        box: {
          w: baseW,
          h: baseH,
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'primary_red' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary_red)',
          width: svgW || defaultSize,
          height: svgH || defaultSize
        }
      },
      solid: {
        box: {
          bg: 'checked_bg',
          w: boxW || defaultSize || '24px',
          h: boxH || defaultSize || '24px',
          borderRadius: '4px',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: getSvgHoverFill('text_caption') }
                }
              : undefined
        },
        svg: {
          fill: getSvgFill('text_paragraph'),
          width: svgW || defaultSize || '16px',
          height: svgH || defaultSize || '16px'
        }
      },
      rectangle: {
        box: {
          bg: 'card_bg',
          w: boxW || defaultSize || '28px',
          h: boxH || defaultSize || '20px',
          borderRadius: '8px',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'primary' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary)',
          width: svgW || defaultSize || '16px',
          height: svgH || defaultSize || '16px'
        }
      },
      round: {
        box: {
          bg: 'card_bg',
          w: boxW || defaultSize || '20px',
          h: boxH || defaultSize || '20px',
          borderRadius: '50%',
          border: '1px solid',
          borderColor: 'var(--chakra-colors-border)',
          background: 'var(--chakra-colors-bg_secondary)',
          _hover:
            !clicked && !isApp
              ? {
                  svg: { fill: 'text_caption' }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || defaultSize || '16px',
          height: svgH || defaultSize || '16px'
        }
      }
    }

    // 返回对应 variant 样式
    return variants[variant] || variants.base
  }, [variant, svgW, svgH, boxW, boxH, fontSize, svgFill, svgHover, isActive, activeColor, activeHoverColor, clicked, isApp])

  return (
    <Center cursor={iconCursor} {...style.box} {...rest} onClick={handleClick}>
      <svg aria-hidden="true" {...style.svg}>
        <use xlinkHref={xlinkHref} />
      </svg>
    </Center>
  )
}
