import useGetTokenSource from '@cetus/hooks/src/useGetTokenSource'
import useTokenStore from '@cetus/stores/src/token'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Center, CenterProps, Flex, HTMLChakraProps, Image, ImageProps } from '@chakra-ui/react'
import { useMemo } from 'react'
import IconTipsTriangle from '/images/token-warning@2x.png'
export const placeholderImg =
  'data:image/png;base64,'

export interface SingleCoinImageProps extends HTMLChakraProps<'div'> {
  imageUrl?: string
  variant?: 'border' | ''
  showTag?: boolean
  coinType?: string
  showTagWidth?: string
  showTagHeight?: string
  imageStyle?: ImageProps
  imgBoxStyle?: CenterProps
  tag_url?: string
  placeholderTagImg?: string
}

export default function SingleCoinImage(props: SingleCoinImageProps) {
  const {
    coinType,
    variant,
    imageUrl,
    w,
    h,
    p,
    tag_url,
    showTag = true,
    showTagWidth,
    showTagHeight,
    borderColor,
    imageStyle = {},
    imgBoxStyle = {},
    placeholderTagImg = IconTipsTriangle,
    ...rest
  } = props
  const style = useMemo(() => {
    const styles = {
      default: {
        box: {
          border: 'none',
          w: w || '32px',
          h: h || '32px'
        }
      },
      border: {
        box: {
          bg: 'checked_bg',
          border: '1px',
          borderColor: borderColor || 'border',
          borderRadius: '100%',
          w: w || '46px',
          h: w || '46px',
          p: p || '5px'
        }
      }
    }
    return variant ? styles[variant] : styles['default']
  }, [variant, w, borderColor, p])

  const { getShowCoinTag } = useGetTokenSource()
  const { importTokenList } = useTokenSelectStore()
  const { verifiedTokenMap } = useTokenStore()
  const isShowCoinTag = useMemo(() => {
    if (coinType) {
      if (verifiedTokenMap?.size > 0) {
        return getShowCoinTag(coinType)
      }
    }

    return false
  }, [coinType, verifiedTokenMap, importTokenList])

  return (
    <Flex display="flex" position="relative">
      <Center {...style.box} {...imgBoxStyle} {...rest}>
        <Image
          key={imageUrl}
          decoding="async"
          src={imageUrl}
          fallbackSrc={placeholderImg}
          borderRadius="100%"
          w="100%"
          h="100%"
          {...imageStyle}
          minW={imageStyle.w || 'unset'}
          minH={imageStyle.h || 'unset'}
        />
      </Center>
      {isShowCoinTag && showTag && !tag_url && (
        <Image
          decoding="async"
          src={placeholderImg}
          fallbackSrc={placeholderImg}
          w={showTagWidth ? showTagWidth : '16px'}
          h={showTagHeight ? showTagHeight : '16px'}
          right={variant === 'border' ? '1px' : '-3px'}
          style={{ position: 'absolute', bottom: '0px' }}
        />
      )}

      {tag_url && (
        <Image
          key={tag_url}
          bg="bg_secondary"
          p="1.5px"
          borderRadius="50%"
          decoding="async"
          src={tag_url || placeholderTagImg}
          fallbackSrc={placeholderTagImg}
          w={showTagWidth ? showTagWidth : '16px'}
          h={showTagHeight ? showTagHeight : '16px'}
          right={variant === 'border' ? '1px' : '-3px'}
          style={{ position: 'absolute', bottom: '0px' }}
        />
      )}
    </Flex>
  )
}
