import { LocalForageService } from './local-forage-service'

// 单例模式实现
class CommenContentTableImpl extends LocalForageService {
  private static instance: CommenContentTableImpl

  private constructor() {
    super('CetusSite', 'commonContent')
  }

  public static getInstance(): CommenContentTableImpl {
    if (!CommenContentTableImpl.instance) {
      CommenContentTableImpl.instance = new CommenContentTableImpl()
    }
    return CommenContentTableImpl.instance
  }
}

// 为了保持向后兼容，保留静态方法接口
export class CommonContentTable {
  private static table = CommenContentTableImpl.getInstance()

  static async setItem<T>(key: string, value: T): Promise<void> {
    return CommonContentTable.table.setItem(key, value)
  }

  static async getItem<T>(key: string): Promise<T | null> {
    return CommonContentTable.table.getItem(key)
  }

  static async getAllItems<T>(): Promise<Map<string, T> | null> {
    return CommonContentTable.table.getAllItems()
  }

  static async removeItem(key: string): Promise<void> {
    return CommonContentTable.table.removeItem(key)
  }

  static async clear(): Promise<void> {
    return CommonContentTable.table.clear()
  }
}
